import qiskit

def build_constraint_1(qc, problem_qubits, flag, scratch):
    # edge (0,2)
    # qubits: vertex0 (high, low) = (problem_qubits[1], problem_qubits[0])
    #         vertex2 (high, low) = (problem_qubits[5], problem_qubits[4])
    controls = [problem_qubits[1], problem_qubits[0],
                problem_qubits[5], problem_qubits[4]]
    patterns = ['0000', '0011', '1100', '1111', '0101', '1010']
    for pat in patterns:
        # apply X to transform pattern to all-1s
        for i, q in enumerate(controls):
            if pat[i] == '0':
                qc.x(q)
        # controlled flip of flag
        qc.mcx(controls, flag, mode='noancilla')
        # undo X gates
        for i, q in enumerate(controls):
            if pat[i] == '0':
                qc.x(q)
    # invert to get difference (not equal)
    qc.x(flag)

def build_constraint_2(qc, problem_qubits, flag, scratch):
    # edge (1,2)
    controls = [problem_qubits[3], problem_qubits[2],
                problem_qubits[5], problem_qubits[4]]
    patterns = ['0000', '0011', '1100', '1111', '0101', '1010']
    for pat in patterns:
        for i, q in enumerate(controls):
            if pat[i] == '0':
                qc.x(q)
        qc.mcx(controls, flag, mode='noancilla')
        for i, q in enumerate(controls):
            if pat[i] == '0':
                qc.x(q)
    qc.x(flag)

def build_constraint_3(qc, problem_qubits, flag, scratch):
    # edge (2,3)
    controls = [problem_qubits[5], problem_qubits[4],
