def build_constraint_1(qc, problem_qubits, flag, scratch):
    """
    Flips flag iff the subset sum of the 5 weights (3,4,5,14,13) equals 21.
    Uses scratch[0] to accumulate the pattern match and scratch[1:] as ancillas
    for the multi-controlled X gates.
    """
    # The only two subsets that sum to 21:
    patterns = [
        [1, 1, 0, 1, 0],   # {3, 4, 14}
        [1, 0, 1, 0, 1]    # {3, 5, 13}
    ]

    target = scratch[0]
    ancillas = scratch[1:]

    def apply_pattern(pattern):
        # Convert problem_qubits to all‑ones if they match the pattern
        for i, bit in enumerate(pattern):
            if bit == 0:
                qc.x(problem_qubits[i])
        # Multi‑controlled Toffoli: flips target when every control is 1
        qc.mcx(problem_qubits, target, ancilla_qubits=ancillas)
        # Undo the X gates
        for i, bit in enumerate(pattern):
            if bit == 0:
                qc.x(problem_qubits[i])

    # Compute whether any pattern matches (store in target)
    for pat in patterns:
        apply_pattern(pat)

    # Flip flag if target is 1 (constraint satisfied)
    qc.cx(target, flag)

    # Uncompute target back to |0>
    for pat in patterns:
        apply_pattern(pat)
