import qiskit

def build_constraint_1(qc, problem_qubits, flag, scratch):
    a = [11, 6, 5, 11, 6]  # values of the elements
    # 22 in binary (LSB first): 1 0 1 1 0 -> index: [0]=0, [1]=1, [2]=1, [3]=0, [4]=1
    pattern = [0, 1, 1, 0, 1]

    # Helper to apply a controlled increment on scratch (controlled by `ctrl`)
    def controlled_increment(ctrl, reverse=False):
        k_range = range(5)
        if reverse:
            k_range = reversed(k_range)
        for k in k_range:
            if k == 0:
                qc.cx(ctrl, scratch[0])
            else:
                controls = [ctrl] + list(scratch[:k])
                qc.mcx(controls, scratch[k], mode='noancilla')

    # Add each element conditionally
    for i in range(5):
        for _ in range(a[i]):
            controlled_increment(problem_qubits[i], reverse=False)

    # Check equality to 22: flip flag iff sum == 22
    qc.x(flag)                     # start flag = 1
    for j in range(5):
        if pattern[j] == 0:
            # flip flag when scratch[j] == 1 (mismatch)
            qc.cx(scratch[j], flag)
        else:
            # flip flag when scratch[j] == 0 (mismatch)
            qc.x(scratch[j])
            qc.cx(scratch[j], flag)
            qc.x(scratch[j])       # restore scratch[j]

    # Uncompute: subtract in reverse order
    for i in reversed(range(5)):
        for _ in range(a[i]):
            controlled_increment(problem_qubits[i], reverse=True)
